#include <bitset>
#include <stdexcept>
#include <iostream>

int main() {
    std::bitset<8> b;
    try {
        // Valid access
        b.set(5); 

        // Invalid access (index 8 is out of bounds for size 8)
        b.set(8); 
        std::cout << "This line should not be reached.\n";
    } catch (const std::out_of_range& e) {
        std::cerr << "Caught expected exception: " << e.what() << "\n";
    }
    return 0;
}
